CREATE TYPE "TechnicalDocumentType" AS ENUM ('TECHNICAL_SHEET','SDS','DECLARATION_OF_CONFORMITY','CE_DOCUMENT','CERTIFICATE','MANUAL','TEST_REPORT','REGULATORY_DOCUMENT','OTHER_TECHNICAL');
CREATE TYPE "TechnicalDocumentStatus" AS ENUM ('UPLOADED','PROCESSING','READY','REVIEW_REQUIRED','NEEDS_OCR','FAILED','SUPERSEDED');
CREATE TYPE "TechnicalAssociationStatus" AS ENUM ('AUTO_CONFIRMED','REVIEW_REQUIRED','UNMATCHED','REJECTED','MANUALLY_CONFIRMED');
CREATE TYPE "ProductTechnicalStatus" AS ENUM ('COMPLETE','INCOMPLETE','MISSING_EVIDENCE','EXPIRED_EVIDENCE','CONFLICTED','PENDING_REVIEW');
CREATE TYPE "EquivalenceResult" AS ENUM ('IDENTICAL','FUNCTIONALLY_EQUIVALENT','NOT_EQUIVALENT','INSUFFICIENT_EVIDENCE');
CREATE TYPE "TechnicalReviewState" AS ENUM ('EXTRACTED','CONFIRMED','REJECTED','CONFLICTED');
CREATE TYPE "TechnicalBatchItemStatus" AS ENUM ('QUEUED','PROCESSING','COMPLETED','REVIEW_REQUIRED','NEEDS_OCR','FAILED');
CREATE TYPE "EquivalenceReviewStatus" AS ENUM ('AI_PROPOSED','REVIEW_REQUIRED','HUMAN_APPROVED','HUMAN_REJECTED','STALE');
CREATE TYPE "SavingOpportunityType" AS ENUM ('EXACT_PRODUCT_SAVING','EQUIVALENT_PRODUCT_SAVING','PRICE_VARIANCE','INSUFFICIENT_TECHNICAL_EVIDENCE');
CREATE TYPE "SavingOpportunityStatus" AS ENUM ('OPEN','REVIEW_REQUIRED','ACCEPTED','DISMISSED','STALE');

CREATE TABLE "TechnicalDocumentBatch" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"createdByUserId" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'UPLOADED',"totalFiles" INTEGER NOT NULL DEFAULT 0,"completedFiles" INTEGER NOT NULL DEFAULT 0,"failedFiles" INTEGER NOT NULL DEFAULT 0,"reviewRequiredFiles" INTEGER NOT NULL DEFAULT 0,"aiEnabled" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "TechnicalDocumentBatchItem" ("id" TEXT PRIMARY KEY,"batchId" TEXT NOT NULL,"sourceDocumentId" TEXT NOT NULL,"technicalDocumentId" TEXT,"status" "TechnicalBatchItemStatus" NOT NULL DEFAULT 'QUEUED',"attempts" INTEGER NOT NULL DEFAULT 0,"maxAttempts" INTEGER NOT NULL DEFAULT 3,"leaseToken" TEXT,"leaseExpiresAt" TIMESTAMP(3),"lastError" TEXT,"startedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "TechnicalDocument" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"batchId" TEXT,"supplierId" TEXT,"familyKey" TEXT NOT NULL,"documentType" "TechnicalDocumentType" NOT NULL,"title" TEXT NOT NULL,"manufacturer" TEXT,"brand" TEXT,"language" TEXT,"referenceIdentifiers" JSONB,"status" "TechnicalDocumentStatus" NOT NULL DEFAULT 'UPLOADED',"currentVersionId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "TechnicalDocumentVersion" ("id" TEXT PRIMARY KEY,"technicalDocumentId" TEXT NOT NULL,"sourceDocumentId" TEXT NOT NULL,"versionNumber" INTEGER NOT NULL,"revision" TEXT,"revisionDate" TIMESTAMP(3),"validFrom" TIMESTAMP(3),"validUntil" TIMESTAMP(3),"checksum" TEXT NOT NULL,"extractedMetadata" JSONB,"extractedTextHash" TEXT,"interpretationProvider" TEXT NOT NULL DEFAULT 'LOCAL_HEURISTIC',"providerModel" TEXT,"confidence" DECIMAL(5,4),"status" "TechnicalDocumentStatus" NOT NULL DEFAULT 'PROCESSING',"supersededAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "TechnicalDocumentProductAssociation" ("id" TEXT PRIMARY KEY,"technicalDocumentId" TEXT NOT NULL,"canonicalProductId" TEXT NOT NULL,"associationType" TEXT NOT NULL,"confidence" DECIMAL(5,4) NOT NULL,"status" "TechnicalAssociationStatus" NOT NULL,"evidence" JSONB NOT NULL,"explanation" TEXT NOT NULL,"decisionSource" TEXT NOT NULL,"confirmedByUserId" TEXT,"confirmedAt" TIMESTAMP(3),"rejectedAt" TIMESTAMP(3),"version" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "TechnicalEvidenceRequirement" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"categoryId" TEXT NOT NULL,"requirementType" TEXT NOT NULL,"documentType" "TechnicalDocumentType","attributeKey" TEXT,"label" TEXT NOT NULL,"required" BOOLEAN NOT NULL DEFAULT true,"validityRequired" BOOLEAN NOT NULL DEFAULT false,"maxAgeDays" INTEGER,"equivalenceCritical" BOOLEAN NOT NULL DEFAULT false,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "TechnicalProductAttribute" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"canonicalProductId" TEXT NOT NULL,"technicalDocumentVersionId" TEXT NOT NULL,"attributeKey" TEXT NOT NULL,"label" TEXT NOT NULL,"valueText" TEXT NOT NULL,"normalizedValue" DECIMAL(18,6),"unit" TEXT,"confidence" DECIMAL(5,4) NOT NULL,"extractionSource" TEXT NOT NULL,"reviewState" "TechnicalReviewState" NOT NULL DEFAULT 'EXTRACTED',"reviewedByUserId" TEXT,"reviewedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "ProductTechnicalState" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"canonicalProductId" TEXT NOT NULL,"status" "ProductTechnicalStatus" NOT NULL,"completenessPercent" INTEGER NOT NULL,"missingCount" INTEGER NOT NULL DEFAULT 0,"conflictCount" INTEGER NOT NULL DEFAULT 0,"expiredCount" INTEGER NOT NULL DEFAULT 0,"evaluatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"evidenceFingerprint" TEXT NOT NULL);
CREATE TABLE "ProductEquivalenceAssessment" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"productAId" TEXT NOT NULL,"productBId" TEXT NOT NULL,"result" "EquivalenceResult" NOT NULL,"confidence" DECIMAL(5,4) NOT NULL,"matchedCriteria" JSONB NOT NULL,"differingCriteria" JSONB NOT NULL,"blockingDifferences" JSONB NOT NULL,"evidenceSources" JSONB NOT NULL,"explanation" TEXT NOT NULL,"decisionSource" TEXT NOT NULL,"evidenceFingerprint" TEXT NOT NULL,"reviewStatus" "EquivalenceReviewStatus" NOT NULL DEFAULT 'AI_PROPOSED',"decisionReason" TEXT,"decisionFingerprint" TEXT,"reviewedByUserId" TEXT,"reviewedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "MissingEvidenceItem" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"canonicalProductId" TEXT NOT NULL,"comparedProductId" TEXT,"assessmentId" TEXT,"requirementId" TEXT,"requiredField" TEXT,"requiredDocumentType" "TechnicalDocumentType","reason" TEXT NOT NULL,"suggestedEvidence" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'OPEN',"resolvedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "TechnicalSavingOpportunity" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"type" "SavingOpportunityType" NOT NULL,"currentProductId" TEXT NOT NULL,"candidateProductId" TEXT,"currentOfferId" TEXT,"candidateOfferId" TEXT,"assessmentId" TEXT,"baselinePrice" DECIMAL(18,6),"candidatePrice" DECIMAL(18,6),"savingAmount" DECIMAL(18,6),"savingPercent" DECIMAL(9,4),"annualVolume" DECIMAL(18,4),"estimatedAnnualSaving" DECIMAL(18,2),"evidenceComplete" BOOLEAN NOT NULL DEFAULT false,"confidence" DECIMAL(5,4) NOT NULL,"status" "SavingOpportunityStatus" NOT NULL DEFAULT 'OPEN',"reason" TEXT NOT NULL,"provenance" JSONB NOT NULL,"fingerprint" TEXT NOT NULL,"reviewedByUserId" TEXT,"reviewedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);

